        ownerName: extinguisherData.ownerName,
        ownerSurname: extinguisherData.ownerSurname || '',
        houseNumber: extinguisherData.houseNumber,
        village: extinguisherData.village,
        assetNumber: extinguisherData.assetNumber || '',
