        pressureNote: checkData.checkItems.pressure.comment,
        pinStatus: checkData.checkItems.safetyPin.status,
        pinNote: checkData.checkItems.safetyPin.comment,
        hoseStatus: checkData.checkItems.hoseAndNozzle.status,
        hoseNote: checkData.checkItems.hoseAndNozzle.comment,
        bodyStatus: checkData.checkItems.bodyAndLabel.status,
        bodyNote: checkData.checkItems.bodyAndLabel.comment,
        locationStatus: checkData.checkItems.accessibility.status,
        locationNote: checkData.checkItems.accessibility.comment,
        mountStatus: checkData.checkItems.standAndMount.status,
